    case Initialization(msg: String
    )
    case Preprocess(msg: String
    )
    case Inference(msg: String
    )
    case Postprocess(msg: String
    )
    case InvalidInput(msg: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

