public struct FfiConverterTypeRustoBindingError: FfiConverterRustBuffer {
    typealias SwiftType = RustoBindingError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> RustoBindingError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Initialization(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Preprocess(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Inference(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Postprocess(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 5: return .InvalidInput(
            msg: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: RustoBindingError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Initialization(msg):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Preprocess(msg):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Inference(msg):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Postprocess(msg):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .InvalidInput(msg):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(msg, into: &buf)
            
        }
    }
}


